INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20042, 0, 0, "これから行く場所には見たこともない\n恐ろしい魔物がいて、きっとクウカは\n空前絶後の辱めを受けることに……♪", 10, 0, 1, 1, 11, 104511, 1200420010);
