INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20052, 0, 0, "そうかい。\nじゃあまずは、焚火の枝を集める運命を\n受け入れてもらえるかい？", 10, 0, 1, 1, 11, 105611, 1200520010);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20052, "", "", "", "", "", "", "", 91, 0, 1200520011);
