INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20162, 0, 0, "ねねね！\nみんなで記念撮影しよ？\nあとで見返したら絶対エモいっしょ！", 10, 0, 1, 1, 11, 101611, 1201620005);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20162, "", "", "", "", "", "", "", 91, 0, 1201620006);
