INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20172, 0, 0, "おいおい、つまんないこと言うなよ。\n確かに大変だけど、だからこそ\n面白がってみるのも大事だと思うぜ。", 10, 0, 1, 1, 11, 106511, 1201720015);
