INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20182, "", "", "vo_travel_talk_20018_00", 0, "", "", 0, 21, "vo_travel_talk", 1201820003);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20182, 0, 0, "ぜぇ……ぜぇ……！\n本来、このような探索などは文官である\nわたくしの管轄外なのですけれど……！", 10, 0, 1, 1, 11, 118011, 1201820004);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20182, "", "", "", "", "", "", "", 91, 0, 1201820005);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20182, 0.2, "", "travel_topdrama_r_2000_talk_doya_in", 0, "", 1, "travel_topdrama_r_2000_talk_doya_loop", 3, 118011, 1201820006);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20182, "", "", "vo_travel_talk_20018_01", 0, "", "", 0, 21, "vo_travel_talk", 1201820007);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20182, 0, 0, "陛下直々のご命令とあれば、\nこのクレジッタ・キャッシュ！\nご満足いただける大秘宝を、\nなんとしても手に入れてみせますわ！", 10, 0, 1, 1, 11, 118011, 1201820008);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20182, "", "", "", "", "", "", "", 91, 0, 1201820009);
