INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20192, 0, 0, "はぁ……謹んでお断りします。\nそれと悪事というのは露見しないよう、\nこっそりと行うものですよ？", 10, 0, 1, 1, 11, 107011, 1201920010);
INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20192, "", "", "", "", "", "", "", 91, 0, 1201920011);
