INSERT INTO `v1_72310b683a4b9a0238c4a9125791e389d095a8c88562ff64b11c6c0c93bfb1f6` VALUES (20272, 0, 0, "今度はあいつと一緒に……\nどこに行こうかしら。\nエスコートしてもらわなくちゃね。", 10, 0, 1, 1, 11, 123011, 1202720008);
